import { sql, type SQL } from "drizzle-orm";
import { check, customType, jsonb, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";
import type { Locale } from "../../../i18n/config";
import { uuidv7 } from "../uuid";

/** Primary key: UUIDv7 generated by the app, gen_random_uuid() as DB fallback. */
export const pk = () =>
  uuid()
    .primaryKey()
    .default(sql`gen_random_uuid()`)
    .$defaultFn(() => uuidv7());

/** Always timezone-aware timestamps. */
export const tstz = () => timestamp({ withTimezone: true, mode: "date" });

export const createdAt = () => tstz().notNull().defaultNow();
export const updatedAt = () =>
  tstz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** Soft-delete marker for user-facing content that must stay referentially intact. */
export const deletedAt = () => tstz();

export type LocalizedText = Partial<Record<Locale, string>>;

/** Translatable text stored as {"ar": "...", "fr": "..."}. */
export const localized = () => jsonb().$type<LocalizedText>();

export const tsvector = customType<{ data: string }>({
  dataType() {
    return "tsvector";
  },
});

/** CHECK constraint restricting a text column to a closed set of values. */
export function enumCheck(name: string, column: AnyPgColumn, values: readonly string[]) {
  const list = values.map((v) => `'${v.replaceAll("'", "''")}'`).join(", ");
  return check(name, sql`${column} in (${sql.raw(list)})`);
}

/** CHECK constraint helper for arbitrary boolean expressions. */
export function rule(name: string, expression: SQL) {
  return check(name, expression);
}
